const KEY='wurfbild-v1', $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), uid=()=>crypto.randomUUID();
const zones=['Oben links','Oben Mitte','Oben rechts','Mitte links','Mitte','Mitte rechts','Unten links','Unten Mitte','Unten rechts'], origins=['Linksaußen','Rückraum links','Rückraum Mitte','Kreis links','Kreis Mitte','Rückraum rechts','7 Meter','Kreis rechts','Rechtsaußen'], results=['Tor','Gehalten','Daneben'], legacyResults=[...results,'Pfosten / Latte','Geblockt'], turnoverResults=['Technischer Fehler','Ballverlust'];
let db={version:1,teams:[],games:[]},tab='live',activeGame=null,selectedTeam=null,draft={},filter={team:'',player:'',game:''},elapsed=0,running=false,timer=null,editId=null;
try{const raw=localStorage.getItem(KEY);if(raw)db=JSON.parse(raw)}catch{alert('Die gespeicherten Daten konnten nicht geladen werden. Bitte eine Sicherung importieren.');}
const team=id=>db.teams.find(t=>t.id===id), game=()=>db.games.find(g=>g.id===activeGame), teamName=id=>team(id)?.name||'Unbekannt', playerName=(tid,n)=>team(tid)?.players.find(p=>p.number===n)?.name||'', time=s=>`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;
