function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2500)}
function stopClock(){running=false;clearInterval(timer);timer=null}
function selectGame(id){stopClock();activeGame=id;elapsed=game()?.elapsed||0;selectedTeam=game()?.home;draft={};editId=null;tab='live';render()}
function render(){const g=game();$('#app').innerHTML=`<header><div class="brand">WURF<span>BILD</span><div class="header-note" style="letter-spacing:1px;margin-top:5px">DEIN SPIEL. DEINE ANALYSE.</div></div><div class="row"><span class="header-note">Handball · Analyse am Spielfeldrand</span><span class="pill" id="network">${navigator.onLine?'● Online':'● Offline'}</span></div></header><main class="shell"><nav>${[['live','Live-Erfassung'],['games','Spiele'],['analysis','Auswertung'],['teams','Mannschaften'],['data','Datensicherung']].map(([id,n])=>`<button data-tab="${id}" class="${tab===id?'active':''}">${n}</button>`).join('')}</nav>${tab==='live'?liveView(g):tab==='games'?gamesView():tab==='analysis'?analysisView():tab==='teams'?teamsView():dataView()}<footer><span>WURFBILD / Handballanalyse</span><span>Daten auf diesem Gerät · Regelmäßig Sicherung exportieren</span></footer></main>`;bind();}
function liveView(g){if(!g)return `<div class="topline"><div><div class="eyebrow">Bereit für den Anpfiff</div><h1>Jeder Wurf erzählt etwas.</h1><p class="muted">Erfasse dein Spiel. Entdecke die Muster.</p></div><button class="primary" data-action="newGame">＋ Neues Spiel</button></div><div class="card empty"><div class="empty-symbol">◎</div><h2>Deine Analyse beginnt hier</h2><p>Lege Mannschaften und ein Spiel an.<br>Danach erfasst du Würfe mit wenigen Berührungen.</p><button style="margin-top:20px" data-action="newTeam">Mannschaft anlegen</button>${db.games.length?'<button style="margin:10px" data-tab="games">Vorhandenes Spiel öffnen</button>':''}</div>`;
const score=id=>g.shots.filter(s=>s.team===id&&s.result==='Tor').length;
return `<div class="topline"><div><div class="eyebrow">${g.finished?'Abgeschlossenes Spiel':'Am Spielfeldrand'} · ${esc(g.date)}</div><h1>${esc(teamName(g.home))} <span style="color:#91a088">vs.</span> ${esc(teamName(g.away))}</h1><p class="muted">Würfe erfassen · Links und rechts aus Sicht des Werfers</p></div><button data-tab="games">Spiel wechseln</button></div><div class="layout"><section class="card"><div class="card-head"><h2>${editId?'Wurf korrigieren':'Wurf erfassen'}</h2><span class="pill">Manuelle Erfassung</span></div><div class="row">${[g.home,g.away].map(id=>`<button data-team="${id}" class="${selectedTeam===id?'active':''}">${esc(teamName(id))}</button>`).join('')}</div><div class="step"><div class="step-title"><span class="num">1</span> Wer hat geworfen?</div><div class="players">${(team(selectedTeam)?.players||[]).map(p=>`<button data-player="${p.number}" class="${draft.player===p.number?'active':''}"><b>${p.number}</b><small>${esc(p.name||'Spieler')}</small></button>`).join('')}<button data-player="?" class="${draft.player==='?'?'active':''}"><b>?</b><small>Unbekannt</small></button></div>${!team(selectedTeam)?.players.length?'<p class="muted" style="margin-top:10px">Trikotnummern unter „Mannschaften“ ergänzen.</p>':''}</div><div class="step"><div class="step-title"><span class="num">2</span> Wurfposition <span class="muted">optional</span></div><div class="court">${origins.map(o=>`<button data-origin="${o}" class="${draft.origin===o?'active':''}">${o}</button>`).join('')}</div></div><div class="step split"><div><div class="step-title"><span class="num">3</span> Ziel im Tor <span class="muted">optional</span></div><div class="goal">${zones.map((z,i)=>`<button data-zone="${i}" class="${draft.zone===i?'active':''}" aria-label="${z}">${z}</button>`).join('')}</div></div><div><div class="step-title"><span class="num">4</span> Ergebnis</div><div class="results">${results.map(r=>`<button data-result="${r}" class="${draft.result===r?'active':''}">${r}</button>`).join('')}</div></div></div><div class="savebar"><button class="primary" data-action="saveShot" ${!draft.player||!draft.result?'disabled':''}>${editId?'Änderung speichern':'✓ Wurf speichern'}</button><button data-action="resetDraft">Verwerfen</button></div><p class="muted" style="margin-top:10px">Spieler und Ergebnis sind Pflicht. Unbekannte Angaben bleiben offen.</p></section><aside><div class="card score"><div class="eyebrow" style="color:#b7c9ac">Erfasste Tore</div><div class="scoreline"><span>${esc(teamName(g.home))}</span><strong>${score(g.home)} : ${score(g.away)}</strong><span>${esc(teamName(g.away))}</span></div><p style="font-size:11px;color:#bacbb9">Aus erfassten Würfen berechnet</p></div><div class="card"><div class="card-head"><h3>Spielzeit</h3><span class="pill">${g.period||1}. Halbzeit</span></div><div class="row"><input class="clock-input" id="clock" aria-label="Spielzeit Minuten und Sekunden" value="${time(elapsed)}" inputmode="numeric"><button class="${running?'':'primary'}" data-action="clock">${running?'Pause':'▶ Start'}</button></div><div class="row" style="margin-top:12px"><button data-action="period">${g.period===2?'1. Halbzeit':'2. Halbzeit'}</button><button data-action="finish">${g.finished?'Wieder öffnen':'Spiel abschließen'}</button></div><p class="muted" style="margin-top:12px">Zeit antippen, um sie anzupassen.</p></div><div class="card"><div class="card-head"><h3>Letzte Würfe</h3><span class="pill">${g.shots.length} gesamt</span></div>${g.shots.length?g.shots.slice().reverse().map(s=>eventView(s)).join(''):'<div class="empty">Noch kein Wurf erfasst.<br>Der nächste gehört dir.</div>'}</div></aside></div>`}
function eventView(s){return `<div class="event"><div><b>${esc(s.time)} · #${esc(s.player)} ${esc(playerName(s.team,s.player))}</b><small>${esc(teamName(s.team))} · ${esc(s.result)}</small><small>${esc(s.origin||'Position offen')} · ${s.zone==null?'Ziel offen':zones[s.zone]}</small></div><button data-edit="${s.id}" aria-label="Wurf bearbeiten">✎</button></div>`}
function gamesView(){return `<div class="topline"><div><div class="eyebrow">Deine Spielbibliothek</div><h1>Spiele im Überblick</h1><p class="muted">Eigene Spiele und die Begegnungen deiner Liga.</p></div><button class="primary" data-action="newGame">＋ Neues Spiel</button></div><div class="card">${db.games.length?db.games.slice().reverse().map(g=>`<div class="game-row"><div><h3>${esc(teamName(g.home))} – ${esc(teamName(g.away))}</h3><span class="muted">${esc(g.date)} · ${g.shots.length} Würfe · ${g.events?.length||0} Ereignisse · ${g.finished?'Abgeschlossen':'In Bearbeitung'}</span></div><div class="row"><button class="primary" data-open="${g.id}">Spiel öffnen</button><button class="danger" data-deletegame="${g.id}">Löschen</button></div></div>`).join(''):'<div class="empty">Hier erscheinen deine angelegten Spiele.</div>'}</div>`}
function teamsView(){return `<div class="topline"><div><div class="eyebrow">Kader & Trikotnummern</div><h1>Deine Mannschaften</h1><p class="muted">Spieler über mehrere Begegnungen hinweg auswerten.</p></div><button class="primary" data-action="newTeam">＋ Mannschaft</button></div><div class="team-list">${db.teams.map(t=>`<div class="card"><div class="card-head"><h2>${esc(t.name)}</h2><button data-editteam="${t.id}">Bearbeiten</button></div><div class="players">${t.players.map(p=>`<div style="padding:12px;background:#f2f5ed;border-radius:10px;text-align:center"><b>${p.number}</b><small>${esc(p.name||'Spieler')}${playerFlags(p)}</small></div>`).join('')}</div><p class="muted" style="margin-top:15px">${t.players.length} Spieler</p></div>`).join('')||'<div class="card empty">Lege deine erste Mannschaft mit Trikotnummern an.</div>'}</div>`}
