function analysisView(){const shots=filtered(),goals=shots.filter(s=>s.result==='Tor').length,known=shots.filter(s=>s.zone!=null),players=filter.team?team(filter.team)?.players||[]:[];return `<div class="topline"><div><div class="eyebrow">Muster erkennen</div><h1>Das Spiel hinter den Zahlen.</h1><p class="muted">Wurfbilder und Trefferquoten deiner erfassten Spiele.</p></div><button data-action="csv">↓ CSV exportieren</button></div><div class="filters"><select id="filter-team" aria-label="Mannschaft filtern"><option value="">Alle Mannschaften</option>${db.teams.map(t=>`<option value="${t.id}" ${filter.team===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select><select id="filter-player" aria-label="Spieler filtern" ${!filter.team?'disabled':''}><option value="">Alle Spieler</option>${players.map(p=>`<option value="${p.number}" ${filter.player===p.number?'selected':''}>#${p.number} ${esc(p.name)}${playerFlags(p)}</option>`).join('')}</select><select id="filter-game" aria-label="Spiel filtern"><option value="">Alle Spiele</option>${db.games.map(g=>`<option value="${g.id}" ${filter.game===g.id?'selected':''}>${esc(g.date+' · '+teamName(g.home)+' – '+teamName(g.away))}</option>`).join('')}</select></div><div class="stats">${[[shots.length,'Erfasste Würfe'],[goals,'Tore'],[shots.length?Math.round(goals/shots.length*100)+' %':'–','Trefferquote'],[shots.length-known.length,'Zielbereich offen']].map(([v,n])=>`<div class="stat"><strong>${v}</strong><span>${n}</span></div>`).join('')}</div><div class="split"><div class="card"><div class="card-head"><h2>Wurfverteilung im Tor</h2><span class="pill">${known.length} zugeordnet</span></div><div class="goal">${zones.map((z,i)=>{const a=known.filter(s=>s.zone===i),n=a.length;return `<div class="heat" style="background:rgba(171,209,97,${n?Math.min(.85,.15+n/Math.max(known.length,1)):.03})"><div style="text-align:center"><strong>${n}</strong><small>${z}</small><small>${a.filter(s=>s.result==='Tor').length} Tore</small></div></div>`}).join('')}</div><p class="muted" style="margin-top:14px">Aus Sicht des Werfers · Alle Ergebnisse mit erfasstem Zielbereich.</p></div><div class="card"><h2>Ergebnisse</h2><div style="margin-top:20px">${results.map(r=>{const n=shots.filter(s=>s.result===r).length;return `<div style="margin:16px 0"><div class="row" style="justify-content:space-between;font-size:13px"><span>${r}</span><b>${n}</b></div><div style="background:#f0f3e9;height:9px;border-radius:10px;margin-top:7px"><div style="background:#73984d;height:9px;border-radius:10px;width:${shots.length?n/shots.length*100:0}%"></div></div></div>`}).join('')}</div></div></div><div class="card"><h2>Spielervergleich</h2><div class="tablewrap"><table><thead><tr><th>Mannschaft</th><th>Spieler</th><th>Würfe</th><th>Tore</th><th>Quote</th></tr></thead><tbody>${[...new Set(shots.map(s=>s.team+'|'+s.player))].map(k=>{const [tid,p]=k.split('|'),a=shots.filter(s=>s.team===tid&&s.player===p),n=a.filter(s=>s.result==='Tor').length;return `<tr><td>${esc(teamName(tid))}</td><td>#${esc(p)} ${esc(playerName(tid,p))}${playerFlags(team(tid)?.players.find(x=>x.number===p))}</td><td>${a.length}</td><td>${n}</td><td>${Math.round(n/a.length*100)} %</td></tr>`}).join('')||'<tr><td colspan="5">Noch keine Würfe für diese Auswahl.</td></tr>'}</tbody></table></div></div>`}
function dataView(){return `<div class="topline"><div><div class="eyebrow">Alles unter deiner Kontrolle</div><h1>Deine Daten. Gut gesichert.</h1></div></div><div class="notice">Diese erste Version speichert auf diesem Gerät im Browser. Es gibt noch keine Synchronisierung zwischen iPad und Computer. Beim Löschen der Browserdaten können Einträge verloren gehen. Exportiere nach jedem Spiel eine Sicherung.</div><div class="split"><div class="card"><h2>Sicherung exportieren</h2><p class="muted" style="margin:15px 0;line-height:1.8">Alle Mannschaften, Spiele und Würfe als Datei herunterladen. Die Datei lässt sich auf einem anderen Gerät wieder importieren.</p><button class="primary" data-action="backup">↓ Vollständige Sicherung</button></div><div class="card"><h2>Sicherung importieren</h2><p class="muted" style="margin:15px 0;line-height:1.8">Eine WURFBILD-Sicherung wiederherstellen. Der Import ersetzt nach Bestätigung die Daten auf diesem Gerät.</p><input type="file" id="import" accept="application/json,.json" aria-label="Sicherungsdatei auswählen"></div></div><div class="card"><h2>Videoanalyse folgt später</h2><p class="muted" style="margin-top:12px;line-height:1.8">Der erste Schritt ist die manuelle Erfassung. Ein Analyse-Agent und Video-Upload sind in dieser Version noch nicht angebunden.</p></div>`}
function modal(html){$('#dialog').innerHTML=html;$('#dialog').showModal();$('#dialog').querySelector('[data-close]')?.addEventListener('click',()=>$('#dialog').close())}
function teamDialog(id){const t=team(id);modal(`<form id="team-form"><div class="eyebrow">Mannschaft verwalten</div><h2 style="margin-top:8px">${t?'Kader bearbeiten':'Neue Mannschaft'}</h2><label style="margin-top:20px">Mannschaftsname<input name="name" required maxlength="70" value="${esc(t?.name||'')}" placeholder="z. B. TSV Heimteam"></label><label style="margin-top:15px">Spieler: eine Zeile pro Spieler<textarea name="roster" placeholder="7 Max Mustermann&#10;12 Alex Beispiel">${esc(t?.players.map(p=>p.number+' '+p.name).join('\n')||'')}</textarea></label><p class="muted">Trikotnummer (0–99), dann optional der Name. Nummern bitte dauerhaft einem Spieler zuordnen.</p><div class="dialog-actions"><button type="button" data-close>Abbrechen</button><button class="primary">Speichern</button></div></form>`);$('#team-form').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),name=fd.get('name').trim(),lines=fd.get('roster').split('\n').map(l=>l.trim()).filter(Boolean),players=[];if(!name)return;for(const line of lines){const m=line.match(/^(\d{1,2})(?:\s+(.*))?$/);if(!m){toast('Bitte jede Zeile mit einer Trikotnummer beginnen.');return}const number=String(Number(m[1]));if(players.some(p=>p.number===number)){toast('Eine Trikotnummer ist doppelt.');return}players.push({number,name:m[2]||''})}players.sort((a,b)=>+a.number-+b.number);if(t){t.name=name;t.players=players}else db.teams.push({id:uid(),name,players});persist();$('#dialog').close();render()}}
function newGame(){if(db.teams.length<2){toast('Bitte zuerst mindestens zwei Mannschaften anlegen.');tab='teams';render();return}const opts=db.teams.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('');modal(`<form id="game-form"><div class="eyebrow">Neue Begegnung</div><h2 style="margin-top:8px">Ein neues Spiel anlegen</h2><div class="formgrid"><label>Heimteam<select name="home">${opts}</select></label><label>Gastteam<select name="away">${opts}</select></label><label>Minuten pro Halbzeit<select name="halfMinutes"><option value="30">30 Minuten</option><option value="25">25 Minuten</option><option value="20">20 Minuten</option></select></label><label>Datum<input type="date" name="date" required value="${new Date().toLocaleDateString('sv-SE')}"></label></div><div class="dialog-actions"><button type="button" data-close>Abbrechen</button><button class="primary">Spiel starten</button></div></form>`);$('#game-form select[name=away]').selectedIndex=1;$('#game-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(f.get('home')===f.get('away')){toast('Bitte zwei verschiedene Mannschaften auswählen.');return}const g={id:uid(),home:f.get('home'),away:f.get('away'),date:f.get('date'),halfMinutes:Number(f.get('halfMinutes')),elapsed:0,period:1,finished:false,shots:[]};db.games.push(g);persist();$('#dialog').close();selectGame(g.id)}}
function saveShot(){
 const g=game();if(!g||!draft.player||!(results.includes(draft.result)||(editId&&legacyResults.includes(draft.result)))||!draft.origin||draft.zone==null)return;
 const prev=g.shots.find(s=>s.id===editId),opponent=opposingTeam(g,selectedTeam),p=team(selectedTeam)?.players.find(p=>p.number===draft.player);
 const keeper=prev?(Object.hasOwn(draft,'keeper')?draft.keeper:prev.keeper||'?'):keeperValue(g,opponent)||'?';
 const s={id:editId||uid(),team:selectedTeam,player:draft.player,origin:draft.origin,zone:draft.zone,result:draft.result,time:prev?.time||draft.throwTime||time(elapsed),period:prev?.period||g.period,path:prev?.path||[],keeper,keeperTeam:opponent,keeperName:prev&&keeper===prev.keeper&&opponent===prev.keeperTeam?prev.keeperName||'':playerName(opponent,keeper),leftHanded:prev?.player===(draft.player||'?')?prev.leftHanded??Boolean(p?.leftHanded):Boolean(p?.leftHanded),playerIsKeeper:prev?.player===(draft.player||'?')?prev.playerIsKeeper??Boolean(p?.isKeeper):Boolean(p?.isKeeper),source:'manual',reviewed:true};
 if(prev)g.shots[g.shots.indexOf(prev)]=s;else g.shots.push(s);
 if(!prev&&s.result==='Tor')selectedTeam=opponent;
 g.elapsed=elapsed;persist();draft={};editId=null;render();toast('Wurf gespeichert')
}
function saveTurnover(result){
 const g=game();if(!g||!turnoverResults.includes(result))return;
 if(editId&&g.shots.some(s=>s.id===editId)){toast('Bitte zuerst die Wurfkorrektur abschließen.');return}
 const prev=(g.events||[]).find(e=>e.id===editId),p=team(selectedTeam)?.players.find(p=>p.number===draft.player);
 const event={id:prev?.id||uid(),team:selectedTeam,player:draft.player||'?',result,time:prev?.time||time(elapsed),period:prev?.period||g.period,leftHanded:prev?.player===(draft.player||'?')?prev.leftHanded??Boolean(p?.leftHanded):Boolean(p?.leftHanded),playerIsKeeper:prev?.player===(draft.player||'?')?prev.playerIsKeeper??Boolean(p?.isKeeper):Boolean(p?.isKeeper),source:'manual'};
 g.events??=[];if(prev)g.events[g.events.indexOf(prev)]=event;else g.events.push(event);
 if(!prev)selectedTeam=opposingTeam(g,selectedTeam);
 g.elapsed=elapsed;persist();draft={};editId=null;render();toast(result+' gespeichert')
}
function download(name,data,type){const u=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function backup(){download('wurfbild-sicherung-'+new Date().toLocaleDateString('sv-SE')+'.json',JSON.stringify(db,null,2),'application/json')}
function csv(){const rows=[['Spiel','Datum','Halbzeit','Zeit','Mannschaft','Nummer','Spieler','Wurfposition','Zielbereich','Ergebnis','Torhüter-Mannschaft','Torhüter-Nummer','Torhüter-Name','LH','TW'],...db.games.filter(g=>!filter.game||filter.game===g.id).flatMap(g=>[...g.shots,...(g.events||[])].filter(s=>(!filter.team||s.team===filter.team)&&(!filter.player||s.player===filter.player)).map(s=>[teamName(g.home)+' – '+teamName(g.away),g.date,s.period,s.time,teamName(s.team),s.player,playerName(s.team,s.player),s.origin||'',s.zone==null?'':zones[s.zone],s.result,s.keeperTeam?teamName(s.keeperTeam):'',s.keeper||'',s.keeperName||'',(s.leftHanded??team(s.team)?.players.find(p=>p.number===s.player)?.leftHanded)?'LH':'',(s.playerIsKeeper??team(s.team)?.players.find(p=>p.number===s.player)?.isKeeper)?'TW':'']))];download('wurfbild-auswertung.csv','\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(';')).join('\r\n'),'text/csv;charset=utf-8')}
function validImport(d){if(d?.version!==1||!Array.isArray(d.teams)||!Array.isArray(d.games))return false;const ids=new Set();for(const t of d.teams){if(typeof t.id!=='string'||ids.has(t.id)||typeof t.name!=='string'||!Array.isArray(t.players))return false;if(t.color!=null&&!isColor(t.color))return false;ids.add(t.id);const nums=new Set();for(const p of t.players){if(typeof p.number!=='string'||!/^\d{1,2}$/.test(p.number)||nums.has(p.number)||typeof p.name!=='string')return false;if((p.leftHanded!=null&&typeof p.leftHanded!=='boolean')||(p.isKeeper!=null&&typeof p.isKeeper!=='boolean'))return false;nums.add(p.number)}}const gids=new Set(),sids=new Set();for(const g of d.games){if(typeof g.id!=='string'||gids.has(g.id)||!ids.has(g.home)||!ids.has(g.away)||g.home===g.away||typeof g.date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(g.date)||!Array.isArray(g.shots)||!Number.isInteger(g.elapsed)||g.elapsed<0||g.elapsed>59999||![1,2].includes(g.period)||typeof g.finished!=='boolean')return false;if(g.halfMinutes!=null&&![20,25,30].includes(g.halfMinutes))return false;if(g.referenceGoals!=null&&(!Array.isArray(g.referenceGoals)||g.referenceGoals.some(e=>!e||![g.home,g.away].includes(e.team)||typeof e.time!=='string'||!/^\d{2,3}:[0-5]\d$/.test(e.time)||typeof e.player!=='string'||typeof e.playerName!=='string'||!Number.isInteger(e.homeScore)||!Number.isInteger(e.awayScore))))return false;if(g.keepers!=null&&(typeof g.keepers!=='object'||Array.isArray(g.keepers)||Object.entries(g.keepers).some(([id,n])=>![g.home,g.away].includes(id)||typeof n!=='string'||! /^(\d{1,2}|\?|empty)?$/.test(n))))return false;if(g.events!=null&&(!Array.isArray(g.events)||g.events.some(e=>!e||typeof e.id!=='string'||sids.has(e.id)||!([g.home,g.away].includes(e.team))||typeof e.player!=='string'||! /^(\d{1,2}|\?)$/.test(e.player)||!turnoverResults.includes(e.result)||typeof e.time!=='string'||!/^\d{2,3}:[0-5]\d$/.test(e.time)||![1,2].includes(e.period)||(e.leftHanded!=null&&typeof e.leftHanded!=='boolean')||(e.playerIsKeeper!=null&&typeof e.playerIsKeeper!=='boolean')||e.zone!=null||e.origin!=null||(sids.add(e.id),false))))return false;gids.add(g.id);for(const s of g.shots){if(typeof s.id!=='string'||sids.has(s.id)||![g.home,g.away].includes(s.team)||typeof s.player!=='string'||! /^(\d{1,2}|\?)$/.test(s.player)||!legacyResults.includes(s.result)||(s.zone!=null&&(!Number.isInteger(s.zone)||s.zone<0||s.zone>8))||(s.origin!=null&&!origins.includes(s.origin))||typeof s.time!=='string'||!/^\d{2,3}:[0-5]\d$/.test(s.time)||![1,2].includes(s.period))return false;if((s.leftHanded!=null&&typeof s.leftHanded!=='boolean')||(s.playerIsKeeper!=null&&typeof s.playerIsKeeper!=='boolean'))return false;if(s.path!=null&&(!Array.isArray(s.path)||s.path.length>20000||s.path.some(p=>!p||!Number.isFinite(p.x)||!Number.isFinite(p.y)||p.x<0||p.x>1||p.y<0||p.y>1)))return false;if(s.keeper!=null&&(typeof s.keeper!=='string'||! /^(\d{1,2}|\?|empty)?$/.test(s.keeper)))return false;if(s.keeperTeam!=null&&s.keeperTeam!==(s.team===g.home?g.away:g.home))return false;if(s.keeperName!=null&&typeof s.keeperName!=='string')return false;sids.add(s.id)}}return true}
function bind(){document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});document.querySelectorAll('[data-team]').forEach(b=>b.onclick=()=>{selectedTeam=b.dataset.team;draft.player=null;render()});for(const [attr,key,conv] of [['player','player',String],['origin','origin',String],['zone','zone',Number],['result','result',String]])document.querySelectorAll(`[data-${attr}]`).forEach(b=>b.onclick=()=>{const v=conv(b.dataset[attr]);draft[key]=draft[key]===v?null:v;render()});document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>selectGame(b.dataset.open));document.querySelectorAll('[data-editteam]').forEach(b=>b.onclick=()=>teamDialog(b.dataset.editteam));document.querySelectorAll('[data-deletegame]').forEach(b=>b.onclick=()=>{if(confirm('Dieses Spiel mit allen Würfen endgültig löschen?')){if(activeGame===b.dataset.deletegame){stopClock();activeGame=null}db.games=db.games.filter(g=>g.id!==b.dataset.deletegame);persist();render()}});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const s=game().shots.find(s=>s.id===b.dataset.edit);modal(`<h2>Wurf · ${esc(s.time)} · #${esc(s.player)}</h2><p style="margin:16px 0">${esc(s.result)} · ${s.zone==null?'Ziel offen':zones[s.zone]}</p><div class="dialog-actions"><button data-close>Schließen</button><button class="danger" id="remove-shot">Löschen</button><button class="primary" id="edit-shot">Korrigieren</button></div>`);$('#edit-shot').onclick=()=>{editId=s.id;selectedTeam=s.team;draft={...s};$('#dialog').close();render();window.scrollTo({top:0,behavior:'smooth'})};$('#remove-shot').onclick=()=>{if(confirm('Diesen Wurf löschen?')){game().shots=game().shots.filter(x=>x.id!==s.id);persist();$('#dialog').close();render()}}});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>actions[b.dataset.action]?.());for(const k of ['team','player','game']){const el=$('#filter-'+k);if(el)el.onchange=()=>{filter[k]=el.value;if(k==='team')filter.player='';render()}}const c=$('#clock');if(c)c.onchange=()=>{const m=c.value.match(/^(\d{1,3}):([0-5]\d)$/);if(!m){toast('Zeit bitte als MM:SS eingeben.');c.value=time(elapsed);return}stopClock();elapsed=+m[1]*60+(+m[2]);game().elapsed=elapsed;persist();render()};const imp=$('#import');if(imp)imp.onchange=async()=>{try{const file=imp.files[0];if(!file)return;if(file.size>10000000)throw Error();const d=JSON.parse(await file.text());if(!validImport(d))throw Error();if(!confirm('Die aktuellen Daten durch diese Sicherung ersetzen? Vorher gegebenenfalls exportieren.'))return;stopClock();db=d;activeGame=null;draft={};filter={team:'',player:'',game:''};persist();render();toast('Sicherung importiert')}catch{toast('Die Datei ist keine gültige WURFBILD-Sicherung.')}}}
const actions={newTeam:()=>teamDialog(),newGame,saveShot,resetDraft:()=>{draft={};editId=null;render()},backup,csv,clock:()=>{if(running)stopClock();else{running=true;const base=elapsed,start=Date.now(),gid=activeGame;timer=setInterval(()=>{elapsed=Math.min(59999,base+Math.floor((Date.now()-start)/1000));const g=db.games.find(g=>g.id===gid);if(g)g.elapsed=elapsed;if($('#clock')&&document.activeElement!==$('#clock'))$('#clock').value=time(elapsed);if(elapsed%5===0)persist()},500)}render()},period:()=>{stopClock();game().period=game().period===2?1:2;elapsed=game().period===2?1800:0;game().elapsed=elapsed;persist();render()},finish:()=>{stopClock();game().finished=!game().finished;game().elapsed=elapsed;persist();render()}};
window.addEventListener('pagehide',()=>persist());window.addEventListener('online',()=>{if($('#network'))$('#network').textContent='● Online'});window.addEventListener('offline',()=>{if($('#network'))$('#network').textContent='● Offline'});render();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>toast('Offline-Modus derzeit nicht verfügbar.'));
